-- Baseline reproduzível do WASH FLOW: multi-tenant, RLS e dados operacionais.
create extension if not exists pgcrypto;
create schema if not exists private;
create table public.platform_admins(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table public.sites(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique check(slug ~ '^[a-z0-9-]+$'),status text not null default 'active' check(status in ('active','suspended')),created_at timestamptz not null default now());
create table public.site_members(site_id uuid not null references public.sites(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('owner','manager','operator','inspector')),primary key(site_id,user_id));
create table public.vehicles(id uuid primary key default gen_random_uuid(),site_id uuid not null references public.sites(id) on delete cascade,plate text not null,brand text not null,model text not null,vehicle_group text not null,created_at timestamptz not null default now(),unique(site_id,id),unique(site_id,plate));
create table public.wash_queue(id uuid primary key default gen_random_uuid(),site_id uuid not null references public.sites(id) on delete cascade,vehicle_id uuid not null,plate text not null,priority text not null default 'Normal' check(priority in ('Urgente','Alta','Normal')),status text not null default 'NaFila' check(status in ('NaFila','Lavando','AguardandoConferencia','Refazer','Concluido')),notes text,rejection_reason text,created_at timestamptz not null default now(),started_at timestamptz,finished_at timestamptz,foreign key(site_id,vehicle_id) references public.vehicles(site_id,id));
create table public.wash_history(id uuid primary key default gen_random_uuid(),site_id uuid not null references public.sites(id) on delete cascade,vehicle_id uuid not null,plate text not null,priority text not null,completed_at timestamptz not null default now(),duration_seconds integer,source_job_id uuid not null unique,foreign key(site_id,vehicle_id) references public.vehicles(site_id,id));
create index idx_members_user on public.site_members(user_id,site_id);
create index idx_queue_site_status on public.wash_queue(site_id,status,created_at);
create index idx_history_site_date on public.wash_history(site_id,completed_at desc);
create or replace function private.is_platform_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.platform_admins where user_id=(select auth.uid())) $$;
create or replace function private.has_site_role(p_site uuid,p_roles text[]) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.site_members m join public.sites s on s.id=m.site_id where m.site_id=p_site and m.user_id=(select auth.uid()) and m.role=any(p_roles) and s.status='active') $$;
revoke all on function private.is_platform_admin() from public;
revoke all on function private.has_site_role(uuid,text[]) from public;
grant usage on schema private to authenticated;
grant execute on function private.is_platform_admin() to authenticated;
grant execute on function private.has_site_role(uuid,text[]) to authenticated;
alter table public.platform_admins enable row level security;
alter table public.sites enable row level security;
alter table public.site_members enable row level security;
alter table public.vehicles enable row level security;
alter table public.wash_queue enable row level security;
alter table public.wash_history enable row level security;
create policy admin_read on public.platform_admins for select to authenticated using(user_id=(select auth.uid()));
create policy sites_read on public.sites for select to authenticated using(private.is_platform_admin() or private.has_site_role(id,array['owner','manager','operator','inspector']));
create policy sites_insert on public.sites for insert to authenticated with check(private.is_platform_admin());
create policy sites_update on public.sites for update to authenticated using(private.is_platform_admin()) with check(private.is_platform_admin());
create policy members_read on public.site_members for select to authenticated using(private.is_platform_admin() or user_id=(select auth.uid()) or private.has_site_role(site_id,array['owner','manager']));
create policy members_insert on public.site_members for insert to authenticated with check(private.is_platform_admin() or private.has_site_role(site_id,array['owner']));
create policy members_update on public.site_members for update to authenticated using(private.is_platform_admin() or private.has_site_role(site_id,array['owner'])) with check(private.is_platform_admin() or private.has_site_role(site_id,array['owner']));
create policy members_delete on public.site_members for delete to authenticated using(private.is_platform_admin() or private.has_site_role(site_id,array['owner']));
create policy vehicles_read on public.vehicles for select to authenticated using(private.is_platform_admin() or private.has_site_role(site_id,array['owner','manager','operator','inspector']));
create policy vehicles_insert on public.vehicles for insert to authenticated with check(private.is_platform_admin() or private.has_site_role(site_id,array['owner','manager','operator']));
create policy vehicles_update on public.vehicles for update to authenticated using(private.is_platform_admin() or private.has_site_role(site_id,array['owner','manager','operator'])) with check(private.is_platform_admin() or private.has_site_role(site_id,array['owner','manager','operator']));
create policy queue_read on public.wash_queue for select to authenticated using(private.is_platform_admin() or private.has_site_role(site_id,array['owner','manager','operator','inspector']));
create policy queue_insert on public.wash_queue for insert to authenticated with check((private.is_platform_admin() or private.has_site_role(site_id,array['owner','manager','operator'])) and exists(select 1 from public.vehicles v where v.id=vehicle_id and v.site_id=wash_queue.site_id));
create policy queue_update on public.wash_queue for update to authenticated using(private.is_platform_admin() or private.has_site_role(site_id,array['owner','manager','operator','inspector'])) with check(private.is_platform_admin() or private.has_site_role(site_id,array['owner','manager','operator','inspector']));
create policy history_read on public.wash_history for select to authenticated using(private.is_platform_admin() or private.has_site_role(site_id,array['owner','manager','operator','inspector']));
create or replace function public.complete_wash(p_job_id uuid) returns void language plpgsql security definer set search_path='' as $$
declare j public.wash_queue%rowtype;
begin
 select * into j from public.wash_queue where id=p_job_id for update;
 if not found then raise exception 'Lavagem não encontrada'; end if;
 if not (private.is_platform_admin() or private.has_site_role(j.site_id,array['owner','manager','inspector'])) then raise exception 'Sem permissão'; end if;
 if j.status<>'AguardandoConferencia' then raise exception 'Lavagem não está em conferência'; end if;
 insert into public.wash_history(site_id,vehicle_id,plate,priority,source_job_id,duration_seconds) values(j.site_id,j.vehicle_id,j.plate,j.priority,j.id,case when j.started_at is not null then greatest(0,extract(epoch from now()-j.started_at)::integer) else null end);
 update public.wash_queue set status='Concluido',finished_at=now() where id=j.id;
end $$;
revoke all on function public.complete_wash(uuid) from public,anon;
grant execute on function public.complete_wash(uuid) to authenticated;
